    xAxis: { type: 'value', axisLine: { show: false }, axisLabel: { color: 'rgba(148,163,184,0.4)', fontSize: 10 }, splitLine: { lineStyle: { color: 'rgba(148,163,184,0.05)', type: 'dashed' } } },
    yAxis: { type: 'category', data: sorted.map(([n]) => n).reverse(), axisLine: { show: false }, axisLabel: { color: 'rgba(203,213,225,0.7)', fontSize: 12 }, axisTick: { show: false } },
    series: [{
