}

const initBackground = () => {
  const canvas = bgCanvas.value
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  let w, h, stars = [], particles = []
  const resize = () => { w = canvas.width = window.innerWidth; h = canvas.height = window.innerHeight }
  class Star {
    constructor() { this.x = Math.random() * w; this.y = Math.random() * h; this.r = Math.random() * 1.2 + 0.3; this.alpha = Math.random() * 0.8 + 0.2; this.twinkle = Math.random() * 0.02 + 0.005 }
    draw() {
      ctx.beginPath(); ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2)
      ctx.fillStyle = `rgba(200,210,255,${this.alpha})`; ctx.fill()
      this.alpha += (Math.random() - 0.5) * this.twinkle
      if (this.alpha > 1) this.alpha = 1; if (this.alpha < 0.1) this.alpha = 0.1
    }
  }
  class Particle {
    constructor() { this.reset() }
    reset() { this.x = Math.random() * w; this.y = Math.random() * h; this.vx = (Math.random() - 0.5) * 0.15; this.vy = (Math.random() - 0.5) * 0.15; this.r = Math.random() * 1.5 + 0.5; this.c = Math.random() > 0.5 ? '#818cf8' : '#c084fc' }
    update() { this.x += this.vx; this.y += this.vy; if (this.x < 0 || this.x > w || this.y < 0 || this.y > h) this.reset() }
    draw() {
      ctx.beginPath(); ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2)
      const g = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.r * 3)
      g.addColorStop(0, this.c + '66'); g.addColorStop(1, 'transparent')
      ctx.fillStyle = g; ctx.fill()
    }
  }
  const init = () => { stars = []; particles = []; for (let i = 0; i < 180; i++) stars.push(new Star()); for (let i = 0; i < 30; i++) particles.push(new Particle()) }
  const connect = () => {
    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        const dx = particles[i].x - particles[j].x, dy = particles[i].y - particles[j].y
        const d = Math.sqrt(dx * dx + dy * dy)
        if (d < 140) {
          ctx.beginPath(); ctx.moveTo(particles[i].x, particles[i].y); ctx.lineTo(particles[j].x, particles[j].y)
          ctx.strokeStyle = `rgba(129,140,248,${(1 - d / 140) * 0.1})`; ctx.lineWidth = 0.5; ctx.stroke()
        }
      }
    }
  }
  const animate = () => {
    ctx.clearRect(0, 0, w, h)
    stars.forEach(s => s.draw())
    particles.forEach(p => { p.update(); p.draw() })
    connect()
    animationId = requestAnimationFrame(animate)
  }
  resize(); init(); animate()
  window.addEventListener('resize', () => { resize(); init() })
}

const handleResize = () => { salaryInstance?.resize(); cityInstance?.resize() }

onMounted(() => {
  initSalaryChart(); initCityChart(); initBackground(); loadPolicyData()
  window.addEventListener('resize', handleResize)
})
onUnmounted(() => {
  window.removeEventListener('resize', handleResize)
  salaryInstance?.dispose(); cityInstance?.dispose()
  if (animationId) cancelAnimationFrame(animationId)
})
